/*!50003 CREATE*/ /*!50017 DEFINER=`Marianna.Gayosso`@`%`*/ /*!50003 TRIGGER `trg_tb_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
    DECLARE changes_detail TEXT DEFAULT '';

    IF NOT (OLD.SKU <=> NEW.SKU) THEN
        SET changes_detail = CONCAT(changes_detail,
            'SKU: \"', OLD.SKU, '\" -> \"', NEW.SKU, '\"; ');
    END IF;

    IF NOT (OLD.name <=> NEW.name) THEN
        SET changes_detail = CONCAT(changes_detail,
            'Nombre: \"', OLD.name, '\" -> \"', NEW.name, '\"; ');
    END IF;

    IF NOT (OLD.description <=> NEW.description) THEN
        SET changes_detail = CONCAT(changes_detail, 'Descripcion: modificada; ');
    END IF;

    IF NOT (OLD.current_price <=> NEW.current_price) THEN
        SET changes_detail = CONCAT(changes_detail,
            'Precio: $', OLD.current_price, ' -> $', NEW.current_price, '; ');
    END IF;

    IF NOT (OLD.current_stock <=> NEW.current_stock) THEN
        SET changes_detail = CONCAT(changes_detail,
            'Stock: ', OLD.current_stock, ' -> ', NEW.current_stock, '; ');
    END IF;

    IF NOT (OLD.status <=> NEW.status) THEN
        SET changes_detail = CONCAT(changes_detail,
            'Estado: ', IFNULL(CAST(OLD.status AS UNSIGNED), 'NULL'),
            ' -> ', IFNULL(CAST(NEW.status AS UNSIGNED), 'NULL'), '; ');
    END IF;

    IF CHAR_LENGTH(changes_detail) > 0 THEN
        INSERT INTO tb_logs (
            table_name, record_id, table_operation, db_user, operation_description
        )
        VALUES (
