CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_new_user`(
    IN p_email          VARCHAR(100),
    IN p_nick           VARCHAR(50),
    IN p_password       VARCHAR(255),
    IN p_courtesy_title VARCHAR(20),
    IN p_given_names    VARCHAR(150),
    IN p_family_names   VARCHAR(150),
    IN p_birth_date     DATE,
    IN p_gender         VARCHAR(30),
    IN p_country_code   CHAR(2),
    IN p_phone          VARCHAR(25)
)
BEGIN
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_user_id INT DEFAULT NULL;
    DECLARE v_person_id BIGINT UNSIGNED DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET p_email = LOWER(TRIM(p_email));
    SET p_nick = TRIM(p_nick);
    SET p_given_names = TRIM(p_given_names);
    SET p_family_names = NULLIF(TRIM(p_family_names), '');
    SET p_courtesy_title = NULLIF(TRIM(p_courtesy_title), '');
    SET p_gender = COALESCE(NULLIF(TRIM(p_gender), ''), 'Prefiero no decirlo');
    SET p_country_code = NULLIF(UPPER(TRIM(p_country_code)), '');
    SET p_phone = NULLIF(TRIM(p_phone), '');

    SELECT COUNT(*) INTO v_count FROM tb_user WHERE email = p_email;
    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El correo electrónico ya se encuentra registrado';
    END IF;

    SELECT COUNT(*) INTO v_count FROM tb_user WHERE nick = p_nick;
    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El nick ya se encuentra en uso';
    END IF;

    START TRANSACTION;

    INSERT INTO tb_user (email, nick, password) VALUES (p_email, p_nick, MD5(p_password));
    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO tb_people (user_ID, courtesy_title, given_names, family_names, birth_date, gender, country_code, phone)
    VALUES (v_user_id, p_courtesy_title, p_given_names, p_family_names, p_birth_date, p_gender, p_country_code, p_phone);
    SET v_person_id = LAST_INSERT_ID();

    COMMIT;

    SELECT 'Usuario y persona registrados correctamente' AS mensaje, v_user_id AS user_id, v_person_id AS person_id;
END ;;
DELIMITER ;
